<script>
window.keyanAdminPush = { publicKey: @json(config('services.webpush.public_key')), subscribeUrl: @json(route('admin.push-subscriptions.store')) };
(function () {
    const button = document.getElementById('enablePushButton');
    const status = document.getElementById('pushStatus');
    if (!button || !status) return;
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) { status.textContent = 'Push is not supported by this browser'; status.classList.add('warn'); return; }
    const encodeKey = value => { const padding = '='.repeat((4 - value.length % 4) % 4); const raw = atob((value + padding).replace(/-/g, '+').replace(/_/g, '/')); return Uint8Array.from([...raw].map(char => char.charCodeAt(0))); };
    button.addEventListener('click', async function () {
        if (!window.keyanAdminPush.publicKey) { status.textContent = 'Add VAPID keys to enable push'; status.classList.add('warn'); return; }
        button.disabled = true;
        try {
            const permission = await Notification.requestPermission();
            if (permission !== 'granted') throw new Error('Notification permission was not granted.');
            const registration = await navigator.serviceWorker.register('/service-worker.js');
            let subscription = await registration.pushManager.getSubscription();
            subscription = subscription || await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: encodeKey(window.keyanAdminPush.publicKey) });
            const response = await fetch(window.keyanAdminPush.subscribeUrl, { method: 'POST', headers: {'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}, body: JSON.stringify(subscription.toJSON()) });
            if (!response.ok) throw new Error('Could not save this device.');
            status.textContent = 'Mobile alerts are enabled'; status.classList.add('ready'); button.textContent = 'Alerts enabled';
        } catch (error) { status.textContent = error.message || 'Could not enable alerts'; status.classList.add('warn'); }
        button.disabled = false;
    });
})();
</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const sidebar = document.querySelector('.sidebar');
    const toggle = document.querySelector('.admin-menu-toggle');
    if (!sidebar || !toggle) return;

    const setOpen = open => {
        sidebar.classList.toggle('is-open', open);
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        toggle.querySelector('.admin-menu-toggle-icon').textContent = open ? '×' : '☰';
    };

    toggle.addEventListener('click', () => setOpen(!sidebar.classList.contains('is-open')));
    sidebar.querySelectorAll('.nav-link').forEach(link => link.addEventListener('click', () => setOpen(false)));
    window.addEventListener('resize', () => {
        if (window.innerWidth > 980) setOpen(false);
    });
});
</script>
